#!/usr/bin/env bun
import{text}from"node:stream/consumers";function padTwoDigits(value){return value.toString().padStart(2,`0`)}function formatTimeContext(now){return`<time>${padTwoDigits(now.getHours())}:${padTwoDigits(now.getMinutes())}</time>`}function promptTimeHandler(_event){return{hookSpecificOutput:{hookEventName:`UserPromptSubmit`,additionalContext:formatTimeContext(new Date)}}}function promptTimeParser(raw){return JSON.parse(raw)}function promptTimeWriter(output){return JSON.stringify(output)}async function runHookPlugin({parser,handler,writer}){let output=await handler(parser(await text(process.stdin)));process.stdout.write(writer(output))}await runHookPlugin({parser:promptTimeParser,handler:promptTimeHandler,writer:promptTimeWriter});export{};